/** Edits only this app's personal library; no receiver firmware/channel database access. */
public final class ChannelsActivity extends HubActivity {
    private static final int PLAYLIST=201,EPG=202,IMPORT_JSON=203,EXPORT_JSON=204,PAGE=60;
    private final ExecutorService worker=Executors.newSingleThreadExecutor(),logos=Executors.newSingleThreadExecutor(),searchWorker=Executors.newSingleThreadExecutor();
    private volatile boolean closed;
    private PlaylistRepository repository;
    private LinearLayout body,results;
    private TextView status,count;
    private EditText search;
    private boolean favorites,hidden;
    private String group="";
    private int page;
    private long logoRequest;
    private volatile int searchGeneration;

    @Override public void onCreate(Bundle state){super.onCreate(state);body=page(tx("مكتبتي التلفزيونية","My TV library"),tx("قوائمك الشخصية ودليل البرامج داخل IRAQhub","Your personal playlists and programme guide inside IRAQhub"));status=text(tx("جارٍ تحميل المكتبة…","Loading library…"),15,false);body.addView(status);worker.execute(()->{repository=new PlaylistRepository(this);runOnUiThread(()->{if(!closed)build();});});}
    private void build(){body.removeAllViews();
        LinearLayout tools=card(body);note(tools,tx("استورد ملفك أو رابطك الذي تملك حق استخدامه. التعديلات تخص مكتبة التطبيق؛ لا تغيّر قائمة القنوات في نظام الرسيفر.","Import a file or URL you are entitled to use. Changes affect this app's library, not the receiver's system channel list."));
        LinearLayout imports=row();small(imports,tx("ملف M3U","M3U file"),()->openFile(PLAYLIST));small(imports,tx("رابط قائمة","Playlist URL"),()->urlImport(false));small(imports,tx("دليل XMLTV","XMLTV guide"),this::epgOptions);tools.addView(imports);
        LinearLayout backup=row();small(backup,tx("تصدير JSON","Export JSON"),()->{noteExport();});small(backup,tx("استيراد JSON","Import JSON"),()->openFile(IMPORT_JSON));small(backup,tx("استعادة الأصل","Restore original"),this::restore);tools.addView(backup);
        search=field(body,tx("بحث قناة / برنامج / فئة / وقت / T9","Search channel / programme / category / time / T9"),"");search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int st,int b,int c){page=0;render();}});
        LinearLayout filters=row();CheckBox fav=new CheckBox(this);fav.setText(tx("المفضلة فقط","Favorites only"));fav.setTextColor(WHITE);fav.setChecked(favorites);fav.setOnCheckedChangeListener((b,on)->{favorites=on;page=0;render();});filters.addView(fav);CheckBox hide=new CheckBox(this);hide.setText(tx("إظهار المخفية","Include hidden"));hide.setTextColor(WHITE);hide.setChecked(hidden);hide.setOnCheckedChangeListener((b,on)->{hidden=on;page=0;render();});filters.addView(hide);body.addView(filters);
        List<String> groups=new ArrayList<>();groups.add(tx("كل المجموعات","All groups"));Set<String> names=new TreeSet<>();for(PlaylistRepository.Channel c:repository.all())if(!c.group.isEmpty())names.add(c.group);groups.addAll(names);Spinner spinner=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,groups);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);spinner.setAdapter(adapter);spinner.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,android.view.View v,int pos,long id){group=pos==0?"":groups.get(pos);if(v instanceof TextView)((TextView)v).setTextColor(WHITE);page=0;render();}public void onNothingSelected(android.widget.AdapterView<?> p){}});body.addView(spinner);
        count=text("",14,false);count.setTextColor(ACCENT);body.addView(count);status=text("",13,false);status.setTextColor(MUTED);body.addView(status);results=col();body.addView(results);render();
    }
    private void small(LinearLayout parent,String label,Runnable run){Button b=button(label);b.setTextSize(13);b.setOnClickListener(v->run.run());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(0,dp(4),dp(6),dp(4));parent.addView(b,p);}
    private void render(){if(repository==null||results==null)return;final int request=++searchGeneration;final String query=search==null?"":search.getText().toString(),selectedGroup=group;final boolean onlyFavorites=favorites,includeHidden=hidden;searchWorker.execute(()->{if(closed||request!=searchGeneration)return;List<PlaylistRepository.Channel> all=repository.search(query,onlyFavorites,includeHidden),list=new ArrayList<>();for(PlaylistRepository.Channel c:all)if(selectedGroup.isEmpty()||selectedGroup.equals(c.group))list.add(c);runOnUiThread(()->{if(!closed&&request==searchGeneration)renderMatches(list);});});}
    private void renderMatches(List<PlaylistRepository.Channel> list){int totalPages=Math.max(1,(list.size()+PAGE-1)/PAGE);page=Math.max(0,Math.min(page,totalPages-1));results.removeAllViews();count.setText(tx(repository.all().size()+" قناة محفوظة • "+repository.epgCount()+" برنامج • "+list.size()+" نتيجة",repository.all().size()+" saved channels • "+repository.epgCount()+" programmes • "+list.size()+" matches"));
        if(list.isEmpty()){note(results,tx("لا توجد قنوات مطابقة. استورد قائمتك أو غيّر البحث.","No channels match. Import your playlist or change the filters."));return;}
        LinearLayout pagination=row();small(pagination,tx("السابقة","Previous"),()->{if(page>0){page--;render();}});TextView pages=text((page+1)+" / "+totalPages,14,true);pages.setGravity(Gravity.CENTER);pagination.addView(pages,new LinearLayout.LayoutParams(dp(90),-2));small(pagination,tx("التالية","Next"),()->{if((page+1)*PAGE<list.size()){page++;render();}});results.addView(pagination);
        long now=System.currentTimeMillis();for(int i=page*PAGE;i<Math.min(list.size(),(page+1)*PAGE);i++){PlaylistRepository.Channel c=list.get(i);LinearLayout card=card(results),line=row();ImageView logo=logo(c.logo);line.addView(logo,new LinearLayout.LayoutParams(dp(48),dp(48)));Button play=button((c.favorite?"★ ":"")+c.name+(c.hidden?tx(" • مخفية"," • hidden"):""));play.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);play.setOnClickListener(v->play(c));line.addView(play,new LinearLayout.LayoutParams(0,-2,1));Button edit=button(tx("إدارة","Manage"));edit.setOnClickListener(v->manage(c));line.addView(edit,new LinearLayout.LayoutParams(dp(110),-2));card.addView(line);PlaylistRepository.Programme current=repository.now(c,now);note(card,(c.group.isEmpty()?"":c.group+" • ")+(current==null?tx("لا توجد معلومات برنامج حالي مرتبطة","No linked current programme information"):tx("الآن: ","Now: ")+current.title+"  "+time(current.startMs)+"–"+time(current.endMs))+(c.catchup.isEmpty()?"":tx(" • بيانات إعادة متاحة في القائمة"," • playlist advertises catch-up")));}
    }
    private void play(PlaylistRepository.Channel c){startActivity(new Intent(this,PlayerActivity.class).putExtra("channelId",c.id));}
    private void manage(PlaylistRepository.Channel c){String[] options={tx("تشغيل","Play"),tx(c.favorite?"إزالة من المفضلة":"إضافة للمفضلة",c.favorite?"Remove favorite":"Add favorite"),tx("تعديل الاسم والمجموعة ومعرّف الدليل","Edit name, group and guide ID"),tx(c.hidden?"إظهار القناة":"إخفاء القناة المعطلة",c.hidden?"Unhide channel":"Hide broken channel"),tx("تحريك للأعلى","Move up"),tx("تحريك للأسفل","Move down"),tx("دليل برامج القناة","Programme guide")};new AlertDialog.Builder(this).setTitle(c.name).setItems(options,(d,index)->{if(index==0)play(c);else if(index==1){c.favorite=!c.favorite;save(c);}else if(index==2)rename(c);else if(index==3){c.hidden=!c.hidden;save(c);}else if(index==4||index==5)worker.execute(()->{try{repository.move(c.id,index==4?-1:1);refresh();}catch(Exception e){failure();}});else schedule(c);}).show();}
    private void save(PlaylistRepository.Channel c){worker.execute(()->{try{repository.update(c);refresh();}catch(Exception e){failure();}});}
    private void rename(PlaylistRepository.Channel c){LinearLayout fields=col();fields.setPadding(dp(16),dp(8),dp(16),0);EditText name=field(fields,tx("اسم القناة","Channel name"),c.name),category=field(fields,tx("المجموعة","Group"),c.group),guide=field(fields,tx("معرّف XMLTV مطابق تماماً","Exact XMLTV channel ID"),c.tvgId);new AlertDialog.Builder(this).setTitle(tx("تعديل بيانات القناة","Edit channel")).setView(fields).setPositiveButton(tx("حفظ","Save"),(d,w)->{String n=name.getText().toString().trim();if(n.isEmpty()){toast(tx("الاسم مطلوب","Name is required"));return;}c.name=n.substring(0,Math.min(n.length(),150));c.group=category.getText().toString().trim();c.tvgId=guide.getText().toString().trim();save(c);}).setNegativeButton(tx("إلغاء","Cancel"),null).show();}
    private void schedule(PlaylistRepository.Channel c){List<PlaylistRepository.Programme> items=repository.schedule(c);if(items.isEmpty()){toast(tx("لا يوجد دليل مرتبط. استورد XMLTV أو صحّح معرّف القناة.","No linked guide. Import XMLTV or edit the channel ID."));return;}List<PlaylistRepository.Programme> visible=new ArrayList<>();long from=System.currentTimeMillis()-24*60*60*1000L;for(PlaylistRepository.Programme p:items)if(p.endMs>=from&&visible.size()<100)visible.add(p);if(visible.isEmpty())visible.addAll(items.subList(Math.max(0,items.size()-100),items.size()));String[] labels=new String[visible.size()];for(int i=0;i<labels.length;i++){PlaylistRepository.Programme p=visible.get(i);labels[i]=date(p.startMs)+" "+time(p.startMs)+"–"+time(p.endMs)+"  "+p.title+(p.repeat?tx(" [إعادة]"," [repeat]"):"");}new AlertDialog.Builder(this).setTitle(c.name).setItems(labels,(d,i)->{PlaylistRepository.Programme p=visible.get(i);new AlertDialog.Builder(this).setTitle(p.title).setMessage(date(p.startMs)+"  "+time(p.startMs)+"–"+time(p.endMs)+"\n"+p.category+"\n\n"+p.description+(p.repeat?tx("\n\nالبرنامج معلّم كإعادة في XMLTV؛ هذا لا يضمن رابط مشاهدة مسجل.","\n\nXMLTV marks this as a repeat; this does not imply a playable catch-up link."):"")).setPositiveButton(tx("إغلاق","Close"),null).show();}).setNegativeButton(tx("إغلاق","Close"),null).show();}
    private void restore(){new AlertDialog.Builder(this).setTitle(tx("استعادة ترتيب وأسماء القائمة","Restore playlist order and names")).setMessage(tx("سيُعاد ترتيب وأسماء "+repository.all().size()+" قناة كما كانت عند الاستيراد، وتُظهر القنوات المخفية. لن تُحذف القنوات أو المفضلة.","Reset names and order for "+repository.all().size()+" channels to their imported values and unhide hidden entries. Channels and favorites are retained.")).setPositiveButton(tx("استعادة","Restore"),(d,w)->worker.execute(()->{try{repository.restoreOriginal();refresh();}catch(Exception e){failure();}})).setNegativeButton(tx("إلغاء","Cancel"),null).show();}
    private void openFile(int type){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);try{launchDocument(i,type);}catch(Exception e){toast(tx("منتقي الملفات غير متاح","File picker is unavailable"));}}
    private void epgOptions(){new AlertDialog.Builder(this).setTitle(tx("استيراد دليل البرامج XMLTV","Import XMLTV guide")).setItems(new String[]{tx("ملف XMLTV","XMLTV file"),tx("رابط XMLTV","XMLTV URL")},(d,w)->{if(w==0)openFile(EPG);else urlImport(true);}).show();}
    private void urlImport(boolean epg){LinearLayout content=col();content.setPadding(dp(18),dp(10),dp(18),0);EditText input=field(content,tx("رابطك الشخصي عبر HTTP أو HTTPS","Your personal HTTP or HTTPS URL"),"");input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);new AlertDialog.Builder(this).setTitle(epg?"XMLTV":"M3U / M3U8").setView(content).setPositiveButton(tx("جلب ومعاينة","Fetch and preview"),(d,w)->{String url=input.getText().toString().trim();if(!(url.startsWith("https://")||url.startsWith("http://"))||!PlaylistRepository.validStream(url)){toast(tx("أدخل رابط HTTP أو HTTPS صالحاً","Enter a valid HTTP or HTTPS URL"));return;}working();worker.execute(()->{try{String data=download(url);preview(data,url,epg?EPG:PLAYLIST);}catch(Exception e){failure();}});}).setNegativeButton(tx("إلغاء","Cancel"),null).show();}
    private static String download(String address)throws IOException{HttpURLConnection c=(HttpURLConnection)new URL(address).openConnection();c.setConnectTimeout(7000);c.setReadTimeout(12000);c.setRequestProperty("User-Agent","SmartHubPlus/1.0 personal-playlist");try{if(c.getResponseCode()!=200)throw new IOException("Playlist server unavailable");try(InputStream in=c.getInputStream()){return PlaylistRepository.readBounded(in);}}finally{c.disconnect();}}
    private void preview(String data,String source,int type)throws Exception{if(type==EPG){List<PlaylistRepository.Programme> guide=PlaylistRepository.parseXmlTv(data);runOnUiThread(()->{if(closed)return;new AlertDialog.Builder(this).setTitle(tx("معاينة دليل البرامج","Programme guide preview")).setMessage(tx("تم قراءة "+guide.size()+" برنامج صالح. سيستبدل الاستيراد الدليل الحالي ("+repository.epgCount()+" برنامجاً).","Read "+guide.size()+" valid programmes. This replaces the current guide ("+repository.epgCount()+" programmes).")+"\n"+(guide.isEmpty()?tx("لم توجد برامج ذات وقت صالح.","No programmes with valid times found."):guide.get(0).title)).setPositiveButton(tx("استبدال الدليل","Replace guide"),(d,w)->worker.execute(()->{try{repository.saveEpg(guide);refresh();}catch(Exception e){failure();}})).setNegativeButton(tx("إلغاء","Cancel"),null).show();});return;}
        if(type==IMPORT_JSON){org.json.JSONObject root=new org.json.JSONObject(data);org.json.JSONArray incoming=root.optJSONArray("channels");if(!"SmartHubPlusLibrary".equals(root.optString("format"))||incoming==null)throw new IOException("Invalid library");runOnUiThread(()->{if(closed)return;new AlertDialog.Builder(this).setTitle(tx("استيراد نسخة المكتبة","Import library backup")).setMessage(tx("الملف يحتوي "+incoming.length()+" قناة. سيُستعاد ترتيب وأسماء ومفضلة القنوات المطابقة وتُضاف القنوات الجديدة. تبقى القنوات الأخرى ويُدمج دليل البرامج.","The file contains "+incoming.length()+" channels. Matching names, order and favorites are restored; new channels are added. Other existing channels are retained and guide entries are merged.")).setPositiveButton(tx("استعادة ودمج","Restore and merge"),(d,w)->worker.execute(()->{try{int added=repository.importJson(data);success(added);}catch(Exception e){failure();}})).setNegativeButton(tx("إلغاء","Cancel"),null).show();});return;}
        List<PlaylistRepository.Channel> imported=PlaylistRepository.parseM3u(data,source);StringBuilder names=new StringBuilder();for(int i=0;i<Math.min(imported.size(),25);i++)names.append("• ").append(imported.get(i).name).append('\n');runOnUiThread(()->{if(closed)return;new AlertDialog.Builder(this).setTitle(tx("معاينة "+imported.size()+" قناة صالحة","Preview "+imported.size()+" valid channels")).setMessage(tx("ستُدمج القنوات الجديدة دون حذف مكتبتك الحالية. الروابط المكررة تُتجاوز.\n\n","New channels will be merged without deleting your library. Duplicate stream URLs are skipped.\n\n")+names).setPositiveButton(tx("استيراد","Import"),(d,w)->worker.execute(()->{try{int added=repository.merge(imported);success(added);}catch(Exception e){failure();}})).setNegativeButton(tx("إلغاء","Cancel"),null).show();});}
    private void noteExport(){new AlertDialog.Builder(this).setTitle(tx("تصدير مكتبتك","Export your library")).setMessage(tx("يشمل الملف عناوين البث الشخصية وتعديلات القنوات ودليل البرامج. اختر مكاناً خاصاً لحفظه.","The file includes personal stream addresses, channel settings, and programme guide. Choose a private save location.")).setPositiveButton(tx("اختيار الملف","Choose file"),(d,w)->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/json").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"SmartHubPlus-library.json");try{launchDocument(i,EXPORT_JSON);}catch(Exception e){failure();}}).setNegativeButton(tx("إلغاء","Cancel"),null).show();}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(request==EXPORT_JSON){working();worker.execute(()->{try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException();out.write(repository.exportJson().getBytes(StandardCharsets.UTF_8));runOnUiThread(()->{if(!closed){status.setText(tx("تم تصدير المكتبة","Library exported"));}});}catch(Exception e){failure();}});return;}if(request!=PLAYLIST&&request!=EPG&&request!=IMPORT_JSON)return;try{getContentResolver().takePersistableUriPermission(uri,data.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(Exception ignored){}working();worker.execute(()->{try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException();preview(PlaylistRepository.readBounded(in),uri.toString(),request);}catch(Exception e){failure();}});}
    private void working(){if(status!=null)status.setText(tx("جارٍ قراءة الملف أو الرابط…","Reading file or URL…"));}
    private void success(int added){runOnUiThread(()->{if(!closed){status.setText(tx("أضيفت "+added+" قناة جديدة","Added "+added+" new channels"));render();}});}
    private void refresh(){runOnUiThread(()->{if(!closed){status.setText(tx("تم حفظ التعديلات","Changes saved"));render();}});}
    private void failure(){runOnUiThread(()->{if(!closed){if(status!=null)status.setText(tx("تعذّر الاستيراد أو الحفظ. تحقق من الصيغة والاتصال؛ الحد 24 ميغابايت.","Import or save failed. Check the format and connection; limit is 24 MB."));toast(tx("تعذّر فتح الملف أو الرابط أو حفظ التعديلات","Could not open the file or URL, or save changes"));}});}
    private String time(long value){return DateTimeFormatter.ofPattern("HH:mm").withZone(ZoneId.systemDefault()).format(Instant.ofEpochMilli(value));}
    private String date(long value){return DateTimeFormatter.ofPattern("EEE dd/MM",ar?new Locale("ar"):Locale.getDefault()).withZone(ZoneId.systemDefault()).format(Instant.ofEpochMilli(value));}
    private ImageView logo(String address){ImageView view=new ImageView(this);view.setScaleType(ImageView.ScaleType.FIT_CENTER);if(address==null||!(address.startsWith("https://")||address.startsWith("http://")))return view;logos.execute(()->{HttpURLConnection c=null;try{if(closed)return;String key=hex(address);File cache=new File(getCacheDir(),"channel-logo-"+key+".png");Bitmap bitmap=BitmapFactory.decodeFile(cache.getAbsolutePath());if(bitmap==null){long wait=500-(System.currentTimeMillis()-logoRequest);if(wait>0)Thread.sleep(wait);logoRequest=System.currentTimeMillis();c=(HttpURLConnection)new URL(address).openConnection();c.setConnectTimeout(3000);c.setReadTimeout(4000);if(c.getResponseCode()!=200)return;byte[] bytes;try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>2*1024*1024)return;out.write(buffer,0,n);}bytes=out.toByteArray();}BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(options.outWidth<1||options.outHeight<1||options.outWidth>10000||options.outHeight>10000)return;options.inJustDecodeBounds=false;options.inSampleSize=1;while(options.outWidth/options.inSampleSize>128||options.outHeight/options.inSampleSize>128)options.inSampleSize*=2;bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);if(bitmap!=null)try(FileOutputStream out=new FileOutputStream(cache)){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}}if(bitmap!=null){final Bitmap result=bitmap;runOnUiThread(()->{if(!closed)view.setImageBitmap(result);});}}catch(Exception ignored){}finally{if(c!=null)c.disconnect();}});return view;}
    private String hex(String value)throws Exception{StringBuilder s=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)))s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
    @Override protected void onDestroy(){closed=true;searchGeneration++;worker.shutdownNow();searchWorker.shutdownNow();logos.shutdownNow();super.onDestroy();}
}
